// ==========================================
// CART FUNCTIONS
// ==========================================
function addToCart(id) {
  const p = AppState.products.find(x => x.id === id);
  if (!p) return;

  const existing = AppState.cart.find(x => x.id === id);
  if (existing) {
    existing.qty += 1;
  } else {
    AppState.cart.push({
      id: p.id,
      name: p.name,
      price: p.price,
      image: p.images && p.images[0] ? p.images[0] : '',
      wheel: p.wheel_size,
      qty: 1
    });
  }

  saveCart();
  updateCartBadge();
  showToast(`🛒 "${p.name}" добавлен в корзину!`);
}

function updateCartQty(id, delta) {
  const item = AppState.cart.find(x => x.id === id);
  if (!item) return;

  item.qty += delta;
  if (item.qty <= 0) {
    AppState.cart = AppState.cart.filter(x => x.id !== id);
  }
  saveCart();
  renderCartDrawer();
  updateCartBadge();
}

function saveCart() {
  localStorage.setItem('timetry_cart', JSON.stringify(AppState.cart));
}

function updateCartBadge() {
  const totalQty = AppState.cart.reduce((sum, item) => sum + item.qty, 0);
  const badge = document.getElementById('cart-counter');
  if (badge) badge.textContent = totalQty;
  const mobileBadge = document.getElementById('mobile-cart-count');
  if (mobileBadge) mobileBadge.textContent = totalQty;
}

function toggleCartDrawer() {
  const drawer = document.getElementById('cart-drawer');
  if (drawer) {
    drawer.classList.toggle('open');
    if (drawer.classList.contains('open')) {
      renderCartDrawer();
    }
  }
}

function renderCartDrawer() {
  const body = document.getElementById('cart-drawer-items');
  const totalEl = document.getElementById('cart-drawer-total');
  if (!body) return;

  if (AppState.cart.length === 0) {
    body.innerHTML = `
      <div style="text-align: center; padding: 40px 10px; color: var(--text-muted);">
        <p style="font-size: 2.2rem; margin-bottom: 8px;">🛒</p>
        <p style="font-weight: 700; color: #0f172a;">Ваша корзина пуста</p>
        <p style="font-size: 0.82rem; margin-top: 4px;">Выберите подходящую модель велосипеда в каталоге</p>
      </div>
    `;
    if (totalEl) totalEl.textContent = '0 ₽';
    return;
  }

  let totalSum = 0;
  body.innerHTML = AppState.cart.map(item => {
    totalSum += item.price * item.qty;
    return `
      <div class="cart-line-item">
        ${item.image ? `<img class="cart-line-img" src="${item.image}" alt="${item.name}" />` : '<div style="width: 50px; height: 50px; display: flex; align-items: center; justify-content: center; background: #e2e8f0; border-radius: 6px;">📦</div>'}
        <div style="flex: 1; padding: 0 8px;">
          <h4 class="cart-line-title">${item.name}</h4>
          <div class="cart-line-price">${item.price.toLocaleString('ru-RU')} ₽</div>
        </div>
        <div class="cart-line-qty">
          <button class="cart-qty-btn" onclick="updateCartQty('${item.id}', -1)">-</button>
          <span style="font-size: 0.88rem; font-weight: 800; min-width: 18px; text-align: center;">${item.qty}</span>
          <button class="cart-qty-btn" onclick="updateCartQty('${item.id}', 1)">+</button>
        </div>
      </div>
    `;
  }).join('');

  if (totalEl) totalEl.textContent = `${totalSum.toLocaleString('ru-RU')} ₽`;
}

function openCheckoutModal() {
  if (AppState.cart.length === 0) {
    showToast('⚠️ Ваша корзина пуста');
    return;
  }
  toggleCartDrawer();
  const modal = document.getElementById('checkout-modal');
  if (modal) modal.classList.add('active');
}

// ==========================================
// CHECKOUT FORM SUBMISSION
// ==========================================
async function handleCheckoutSubmit(e) {
  e.preventDefault();
  const name = document.getElementById('checkout-name').value.trim();
  const phone = document.getElementById('checkout-phone').value.trim();
  const city = document.getElementById('checkout-city').value.trim();
  const payment = document.getElementById('checkout-payment').value;

  if (AppState.cart.length === 0) {
    showToast('⚠️ Ваша корзина пуста');
    return;
  }

  const itemsSummary = AppState.cart.map(it => `${it.qty}x ${it.name} (${it.price.toLocaleString('ru-RU')} ₽)`).join('\n');
  const totalSum = AppState.cart.reduce((sum, it) => sum + it.price * it.qty, 0);

  const orderData = {
    name: name,
    phone: phone,
    city: city,
    payment: payment,
    items_summary: itemsSummary,
    total_sum: totalSum,
    cart_items: [...AppState.cart]
  };

  AppState.cart = [];
  saveCart();
  updateCartBadge();
  closeModal('checkout-modal');
  e.target.reset();

  await sendStoreOrder(orderData);
}

// ==========================================
// CALLBACK FORM SUBMISSION
// ==========================================
async function handleCallbackSubmit(e) {
  e.preventDefault();
  const name = document.getElementById('callback-name').value.trim();
  const phone = document.getElementById('callback-phone').value.trim();

  closeModal('callback-modal');
  e.target.reset();

  const orderData = {
    name: name,
    phone: phone,
    city: 'Обратный звонок',
    payment: '—',
    items_summary: 'Запрос звонка консультанта дилера',
    total_sum: 0,
    type: 'callback'
  };

  await sendStoreOrder(orderData);
  showToast('✅ Спасибо! Консультант дилера перезвонит вам в течение 10 минут.');
}

// ==========================================
// REAL ORDER SUBMISSION (GAS + YCF 152-FZ)
// ==========================================
async function sendStoreOrder(orderData) {
  const orderId = 'TM-' + Math.floor(1000 + Math.random() * 9000);
  orderData.order_id = orderId;
  orderData.source = window.location.href;
  orderData.timestamp = new Date().toISOString();

  // 1. Google Apps Script POST
  try {
    fetch(LEAD_ENDPOINT, {
      method: 'POST',
      mode: 'no-cors',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ...orderData,
        type: orderData.type || 'store_order'
      })
    }).catch(err => console.warn('GAS dispatch error:', err));
  } catch (e) {
    console.warn('GAS network issue:', e);
  }

  // 2. Yandex Cloud Function POST (152-FZ + Telegram bot)
  try {
    const tgMessage = `Заказ #${orderId}\nКлиент: ${orderData.name}\nТелефон: ${orderData.phone}\nГород: ${orderData.city}\nОплата: ${orderData.payment}\nСумма: ${orderData.total_sum.toLocaleString('ru-RU')} ₽\n\nТовары:\n${orderData.items_summary}`;

    fetch(YANDEX_152FZ_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: orderData.name,
        company: `TIMETRY STORE (${orderId})`,
        role: orderData.city,
        contact_type: 'Телефон',
        contact: orderData.phone,
        wishes: tgMessage,
        source: window.location.href,
        order_id: orderId,
        type: orderData.type || 'store_order'
      })
    }).catch(err => console.warn('YCF dispatch error:', err));
  } catch (e) {
    console.warn('YCF network issue:', e);
  }

  // Show Success Modal (if not callback)
  if (orderData.type !== 'callback') {
    const successIdEl = document.getElementById('success-order-id');
    if (successIdEl) successIdEl.textContent = orderId;
    openModal('order-success-modal');
  }

  return orderId;
}

// ==========================================
// FAVORITES SYSTEM
// ==========================================
function toggleFavorite(id, e) {
  if (e) e.stopPropagation();
  const idx = AppState.favorites.indexOf(id);
  if (idx > -1) {
    AppState.favorites.splice(idx, 1);
    showToast('Удалено из избранного');
  } else {
    AppState.favorites.push(id);
    showToast('❤️ Добавлено в избранное');
  }
  localStorage.setItem('timetry_favs', JSON.stringify(AppState.favorites));
  updateFavoritesCount();
  applyFilters();
}

function updateFavoritesCount() {
  const favCount = document.getElementById('fav-counter');
  if (favCount) favCount.textContent = AppState.favorites.length;
}

function renderFavoritesModal() {
  const container = document.getElementById('favorites-list-container');
  if (!container) return;

  if (AppState.favorites.length === 0) {
    container.innerHTML = `
      <div style="grid-column: 1/-1; text-align: center; padding: 36px 12px; color: var(--text-muted);">
        <p style="font-size: 2rem; margin-bottom: 8px;">🤍</p>
        <p style="font-weight: 700; color: #0f172a;">Список избранного пуст</p>
        <p style="font-size: 0.85rem; margin-top: 4px;">Нажимайте на сердечко на карточках, чтобы сохранять модели.</p>
      </div>
    `;
    return;
  }

  const favProducts = AppState.products.filter(p => AppState.favorites.includes(p.id));
  container.innerHTML = favProducts.map(p => `
    <div style="background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: 10px; padding: 12px; display: flex; flex-direction: column; justify-content: space-between;">
      <div style="height: 120px; display: flex; align-items: center; justify-content: center; margin-bottom: 8px; background: #fff; border-radius: 6px;">
        <img src="${p.images && p.images[0] ? p.images[0] : ''}" style="max-height: 90%; object-fit: contain;" />
      </div>
      <div>
        <h4 style="font-size: 0.95rem; font-weight: 700; color: #0f172a; margin-bottom: 4px;">${p.name}</h4>
        <div style="color: var(--accent-orange); font-weight: 800; margin-bottom: 10px;">${p.price.toLocaleString('ru-RU')} ₽</div>
      </div>
      <div style="display: flex; gap: 8px;">
        <button class="btn-primary" style="flex: 1; padding: 6px; font-size: 0.8rem;" onclick="addToCart(${p.id})">🛒 В корзину</button>
        <button class="btn-outline" style="padding: 6px 10px; font-size: 0.8rem;" onclick="toggleFavorite(${p.id}); renderFavoritesModal();">✕</button>
      </div>
    </div>
  `).join('');
}

// ==========================================
// CATEGORY SHORTCUT & RESET
// ==========================================
function setCategoryFilter(cat) {
  document.querySelectorAll('.cat-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.cat === cat);
  });
  AppState.activeFilters.category = cat;
  applyFilters();

  const catalogEl = document.getElementById('catalog-section');
  if (catalogEl) {
    catalogEl.scrollIntoView({ behavior: 'smooth' });
  }
}

function resetAllFilters() {
  AppState.activeFilters = {
    category: 'all',
    wheel: 'all',
    height: 'all',
    material: 'all',
    brakes: 'all',
    minPrice: 0,
    maxPrice: 200000,
    search: '',
    sort: 'popular'
  };

  document.querySelectorAll('.cat-btn').forEach(b => b.classList.toggle('active', b.dataset.cat === 'all'));
  document.querySelectorAll('.filter-tag-btn').forEach(p => p.classList.remove('active'));
  const searchInput = document.getElementById('catalog-search-input');
  if (searchInput) searchInput.value = '';
  const sortSelect = document.getElementById('catalog-sort-select');
  if (sortSelect) sortSelect.value = 'popular';
  const minPrice = document.getElementById('min-price-input');
  if (minPrice) minPrice.value = '';
  const maxPrice = document.getElementById('max-price-input');
  if (maxPrice) maxPrice.value = '';

  applyFilters();
  showToast('Фильтры сброшены');
}

// ==========================================
// MODAL & TOAST UTILITIES
// ==========================================
function openModal(id) {
  const modal = document.getElementById(id);
  if (modal) {
    if (id === 'favorites-modal') {
      renderFavoritesModal();
    }
    modal.classList.add('active');
  }
}

function closeModal(id) {
  const modal = document.getElementById(id);
  if (modal) modal.classList.remove('active');
}

function showToast(msg) {
  let container = document.getElementById('toast-container');
  if (!container) {
    container = document.createElement('div');
    container.id = 'toast-container';
    container.className = 'toast-container';
    document.body.appendChild(container);
  }

  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.innerHTML = `<span>${msg}</span>`;
  container.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(10px)';
    setTimeout(() => toast.remove(), 250);
  }, 3000);
}

// ==========================================
// EVENT LISTENERS WIRING
// ==========================================
function initEventListeners() {
  // Category pills
  document.querySelectorAll('.cat-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.cat-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      AppState.activeFilters.category = btn.dataset.cat;
      applyFilters();
    });
  });

  // Filter tags in sidebar
  document.querySelectorAll('.filter-tag-btn').forEach(pill => {
    pill.addEventListener('click', () => {
      const type = pill.dataset.filterType;
      const val = pill.dataset.filterVal;
      const groupPills = pill.parentElement.querySelectorAll('.filter-tag-btn');

      if (pill.classList.contains('active')) {
        pill.classList.remove('active');
        AppState.activeFilters[type] = 'all';
      } else {
        groupPills.forEach(p => p.classList.remove('active'));
        pill.classList.add('active');
        AppState.activeFilters[type] = val;
      }
      applyFilters();
    });
  });

  // Search input
  const searchInput = document.getElementById('catalog-search-input');
  if (searchInput) {
    let timeout = null;
    searchInput.addEventListener('input', (e) => {
      clearTimeout(timeout);
      timeout = setTimeout(() => {
        AppState.activeFilters.search = e.target.value;
        applyFilters();
      }, 200);
    });
  }

  // Sort select
  const sortSelect = document.getElementById('catalog-sort-select');
  if (sortSelect) {
    sortSelect.addEventListener('change', (e) => {
      AppState.activeFilters.sort = e.target.value;
      applyFilters();
    });
  }

  // Price inputs
  const minPriceInput = document.getElementById('min-price-input');
  const maxPriceInput = document.getElementById('max-price-input');
  if (minPriceInput) {
    minPriceInput.addEventListener('input', (e) => {
      AppState.activeFilters.minPrice = Number(e.target.value) || 0;
      applyFilters();
    });
  }
  if (maxPriceInput) {
    maxPriceInput.addEventListener('input', (e) => {
      AppState.activeFilters.maxPrice = Number(e.target.value) || 200000;
      applyFilters();
    });
  }

  // Close modals on backdrop click
  document.querySelectorAll('.modal-overlay').forEach(modal => {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        modal.classList.remove('active');
      }
    });
  });

  // Close modals on ESC key
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      document.querySelectorAll('.modal-overlay.active').forEach(m => m.classList.remove('active'));
      const drawer = document.getElementById('cart-drawer');
      if (drawer && drawer.classList.contains('open')) {
        drawer.classList.remove('open');
      }
    }
  });
}
